import json
import sys
import time

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python batch_eval.py <config_file>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    max_start_rate = config.get("max_start_rate", 4)
    cases = config.get("cases", [])

    for i, case in enumerate(cases):
        start_time = time.time()
        expr = case["expr"]
        value = evaluate_expression(expr)

        if value is not None:
            elapsed = time.time() - start_time
            delay = max(0, 1 / max_start_rate - elapsed)
            time.sleep(delay)

            print(f"{case['id']}\t{value}")
        else:
            print(f"{case['id']}\tError evaluating expression", file=sys.stderr)

if __name__ == "__main__":
    main()
